const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name, size = 18) => {
  const paths = {trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',table:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M3 15h18M9 3v18M15 3v18"/>',link:'<path d="m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 2 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',exam:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 5v16M12 5C9 2 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-2-1-7-2-10 1Z"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',flag:'<path d="M5 22V3m0 0c4-4 10 4 14 0v10c-4 4-10-4-14 0"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',bell:'<path d="M5 16h14l-2-3V9a5 5 0 0 0-10 0v4l-2 3ZM9 20h6"/>'};
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.exam}</svg>`;
};
const button = (text, action, style = '', attrs = '') => `<button class="button ${style}" data-action="${action}" ${attrs}>${text}</button>`;
const badge = (text, style = '') => `<span class="badge ${style}">${text}</span>`;
const passage = '<h3>Bacaan bersama · Ruang publik yang lebih ramah</h3><p>Sejumlah kota menguji penutupan jalan bagi kendaraan pada akhir pekan. Ruang tersebut digunakan untuk berjalan kaki, bersepeda, dan kegiatan warga. Uji coba membantu pemerintah mengumpulkan masukan sebelum menetapkan perubahan permanen.</p><p>Meski banyak warga mendukung, akses bagi penduduk lanjut usia dan pengalihan arus kendaraan tetap perlu diperhatikan.</p>';
const library = [
  {id:'literasi',title:'Literasi Bahasa Indonesia',subject:'Bahasa Indonesia',duration:20,material:passage,instructions:'Baca teks, lalu pilih jawaban yang paling tepat.',questions:[
    {id:'l1',body:'Apa tujuan utama uji coba penutupan jalan?',options:['Mengumpulkan masukan warga sebelum perubahan permanen','Menutup semua akses kendaraan','Menghapus kegiatan warga','Memindahkan seluruh penduduk']},
    {id:'l2',material:'<h3>Materi soal 2 · Catatan survei warga</h3><p>Dari 100 responden, 72 mendukung uji coba, 18 meminta perbaikan akses, dan 10 belum menentukan pilihan.</p>',body:'Berapa responden yang meminta perbaikan akses?',options:['10 orang','18 orang','28 orang','72 orang']},
    {id:'l3',body:'Apa hal yang tetap perlu diperhatikan dalam uji coba?',options:['Harga sepeda baru','Akses warga dan pengalihan lalu lintas','Jadwal ujian sekolah','Jumlah pusat perbelanjaan']}
  ]},
  {id:'matematika',title:'Penalaran Matematika',subject:'Matematika',duration:15,material:'<h3>Tabel bersama · Pengunjung perpustakaan</h3><table><tr><th>Hari</th><th>Pengunjung</th></tr><tr><td>Senin</td><td>120</td></tr><tr><td>Selasa</td><td>150</td></tr><tr><td>Rabu</td><td>180</td></tr></table>',instructions:'Gunakan tabel untuk menjawab ketiga soal.',questions:[
    {id:'m1',body:'Berapa total pengunjung selama tiga hari?',options:['300','350','400','450']},
    {id:'m2',body:'Berapa rata-rata pengunjung per hari?',options:['120','135','150','180']},
    {id:'m3',body:'Berapa persen kenaikan pengunjung dari Senin ke Selasa?',options:['15%','20%','25%','30%']}
  ]},
  {id:'english',title:'English Reading',subject:'Bahasa Inggris',duration:10,material:'<h3>Shared reading · A community garden</h3><p>A neighbourhood turned an empty lot into a community garden. Residents share the harvest and meet every Sunday to maintain the space.</p>',instructions:'Choose the best answer based on the passage.',questions:[
    {id:'e1',body:'What was the empty lot turned into?',options:['A school','A garden','A road','A car park']},
    {id:'e2',body:'When do residents meet?',options:['Every Monday','Every Friday','Every Sunday','Every day']}
  ]}
];
const initialExam = () => ({title:'Tryout TKA — Paket A',navigation:'sequential',timer:'per_test',duration:35,start:'2026-11-07T08:00',end:'2026-11-07T10:00',free:false,checkin:false,leaderboard:false,randomize:false,result:'hidden',release:'',window:15,grace:0,attempts:1,whatsappUrl:'',rulesUrl:'',rulesNote:'',notes:'',image:'',promo:'',sections:[{id:'literasi',presentation:'one_per_page'},{id:'matematika',presentation:'all_on_page'}]});
let exam = initialExam(), sections = structuredClone(exam.sections), view = 'admin-list', tab = 'tests', locked = false, legacy = false;
let session = null, questionIndex = 0, mobileNav = false, toastTimer;
let accessPreview = new URLSearchParams(location.search).get('access')==='upcoming'?'upcoming':'ready';
const previewNow = new Date('2026-11-02T08:00:00+07:00');
const isUpcoming = (e=exam) => !session&&accessPreview==='upcoming'&&!!e.start&&!!(e.end||e.checkin)&&new Date(e.start)>previewNow;
function opensIn(e=exam){const minutes=Math.ceil((new Date(e.start)-previewNow)/60000);return `Dibuka dalam ${minutes>=1440?Math.floor(minutes/1440)+' hari':minutes>=60?Math.floor(minutes/60)+' jam':Math.max(1,minutes)+' menit'}`;}
const test = id => library.find(t => t.id === id);
const totalQuestions = list => list.reduce((n, s) => n + test(s.id).questions.length, 0);
const totalMinutes = list => list.reduce((n, s) => n + test(s.id).duration, 0);
const navigationLabel = e => e.navigation === 'free' ? 'Bebas pindah section' : 'Section berurutan';
const timerLabel = e => e.timer === 'overall' ? 'Satu timer untuk seluruh ujian' : 'Timer terpisah per section';
const presentationLabel = s => s.presentation === 'all_on_page' ? 'Semua soal dalam satu halaman' : 'Satu soal per halaman';
const formatted = value => value ? new Date(value).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) + ' WIB' : 'Tidak diatur';
const dirty = () => JSON.stringify(sections) !== JSON.stringify(exam.sections);
const issues = list => list.flatMap(s => s.presentation === 'all_on_page' && test(s.id).questions.some(q => q.material) ? [{id:s.id,text:`${test(s.id).title}: soal ${test(s.id).questions.findIndex(q=>q.material)+1} punya materi sendiri. Pilih satu soal per halaman, atau pindahkan materi ke materi bersama di sumber Test.`}] : []);
function toast(text){ $('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500); }
function route(next){clearTimeout(toastTimer);$('#toast').style.display='none';view=next;render();window.scrollTo(0,0);}
function summary(e, list = e.sections){return `<div class="summary-line">${icon('arrow')}<div><strong>${navigationLabel(e)}</strong><p>${e.navigation==='free'?'Siswa dapat berpindah dan kembali ke section lain selama waktu ujian masih tersedia.':'Siswa menyelesaikan section sesuai urutan. Section yang sudah diselesaikan tidak dapat dibuka kembali.'}</p></div></div><div class="summary-line">${icon('clock')}<div><strong>${timerLabel(e)}</strong><p>${e.timer==='overall'?`${e.duration} menit sejak mulai. Berpindah section tidak mengulang timer.`:`Durasi mengikuti sumber Test. Total ${totalMinutes(list)} menit untuk ${list.length} section; sisa waktu section tidak dibawa ke section berikutnya.`}</p></div></div><div class="summary-line">${icon('exam')}<div><strong>${totalQuestions(list)} soal · ${list.length} section</strong><p>${e.randomize?'Urutan soal diacak per peserta dan tetap sama ketika halaman dimuat ulang.':'Urutan soal mengikuti susunan Test.'} Tampilan soal dipilih untuk setiap section.</p></div></div>`;}
function shell(content, student = false){return `<aside class="sidebar"><div class="brand"><img src="../../../web/public/brand/logo.svg" alt=""><div><div class="brand-name">abak<span>ACADEMY</span></div><small>${student?'Belajar, tumbuh, berprestasi':'Admin Panel'}</small></div></div><button class="nav-item" disabled>${icon('grid')}<span>Dashboard</span></button><div class="nav-label">${student?'BELAJAR':'MANAJEMEN'}</div><button class="nav-item" disabled>${icon('book')}<span>${student?'Kursus Saya':'Kursus'}</span></button><button class="nav-item active" data-action="${student?'student-list':'admin-list'}">${icon('exam')}<span>${student?'Kompetisi & Tryout':'Exam'}</span></button>${!student?`<button class="nav-item child ${view.startsWith('tests-')?'':'active'}" data-action="admin-list"><span>Ujian</span></button><button class="nav-item child ${view.startsWith('tests-')?'active':''}" data-action="tests-list"><span>Tes</span></button><button class="nav-item child" disabled title="Di luar alur prototype"><span>Bank Soal</span></button>`:''}<button class="nav-item" disabled>${icon('users')}<span>${student?'Profil Saya':'Siswa'}</span></button><div class="sidebar-foot row"><span class="avatar">${student?'S':'A'}</span><div><strong class="small">${student?'Siswa contoh':'Admin Exam'}</strong><div class="subtle small">Akun demo</div></div></div></aside><div class="workspace"><header class="app-header"><div class="search-shell">${icon('search',16)}<span>Cari...</span></div><div class="row"><div class="lang"><b>ID</b><span>EN</span></div><span class="header-icons muted">${icon('bell')}</span><span class="avatar">${student?'S':'A'}</span></div></header><main class="main ${student?'student':''}">${content}</main></div>`;}
function pageHead(title, description, actions='', headingIcon='calendar'){return `<div class="page-head" data-reference="AdminPageHeader"><div class="admin-heading"><div class="admin-title-row"><div class="title-icon">${icon(headingIcon,32)}</div><h1>${esc(title)}</h1></div>${description?`<p>${description}</p>`:''}</div><div class="row">${actions}</div></div>`;}
function adminList(){return shell(`${pageHead('Ujian','Kelola paket ujian dan jadwalnya.',button(`${icon('plus',15)} Buat ujian`,'create','primary'))}<div class="admin-list-toolbar" data-reference="ProductsToolbar / ListToolbar"><div class="admin-list-search">${icon('search',16)}<input data-slot="input" id="exam-search" type="search" placeholder="Cari ujian..." aria-label="Cari ujian"><button class="admin-search-clear" data-action="clear-exam-search" aria-label="Hapus pencarian" hidden>${icon('close',16)}</button></div><span id="exam-count" class="small muted" aria-live="polite">2 ujian</span></div><div class="admin-table-scroll mt" data-reference="ProductsPage table"><table class="admin-table"><thead><tr><th scope="col">Ujian</th><th scope="col">Susunan</th><th scope="col">Cara pengerjaan</th><th scope="col">Waktu pengerjaan</th><th scope="col">Jadwal akses</th></tr></thead><tbody><tr data-exam-row="new"><td><button class="exam-link" data-action="admin-detail">${esc(exam.title)}</button><small>12 terdaftar · ${locked?'2 sesi sudah dimulai':'Belum ada sesi'}</small></td><td>${exam.sections.length} section<small>${totalQuestions(exam.sections)} soal</small></td><td>${navigationLabel(exam)}<small>Tampilan soal per section</small></td><td>${exam.timer==='per_test'?'Per section':`${exam.duration} menit total`}<small>${exam.timer==='per_test'?`Total ${totalMinutes(exam.sections)} menit dari Test`:'Satu timer seluruh ujian'}</small></td><td>${formatted(exam.start)}<small>${exam.end?'sampai '+formatted(exam.end):'Tanpa batas akhir akses'}</small></td></tr><tr data-exam-row="legacy"><td><button class="exam-link" data-action="legacy-detail">Tryout TKA — Paket sebelumnya</button><small>28 terdaftar</small></td><td>Format sebelumnya<small>Pengaturan mengikuti mode</small></td><td>Standard<small>Format sebelumnya</small></td><td>60 menit<small>Timer ujian</small></td><td>Tanpa jadwal akses</td></tr><tr id="empty-search" hidden><td colspan="5" class="admin-table-empty">Tidak ada ujian yang cocok.</td></tr></tbody></table></div><p class="small muted mt">Publikasi dan penjualan dikelola melalui Produk yang memuat ujian ini.</p>`);}

function detail(){
  if(legacy)return shell(`<button class="text-button back" data-action="admin-list">${icon('back',14)} Ujian</button>${pageHead('Tryout TKA — Paket sebelumnya','Format ujian sebelumnya')}<div class="notice warn"><strong>Ujian ini menggunakan format sebelumnya</strong>Perilaku ujian tetap mengikuti mode Standard. Pengaturan section composable tidak diterapkan otomatis.</div><div class="card card-body mt"><dl class="dl"><div><dt>Mode</dt><dd>Standard</dd></div><div><dt>Durasi ujian</dt><dd>60 menit</dd></div><div><dt>Konversi format</dt><dd>Di luar lingkup prototype</dd></div></dl></div>`);
  return shell(`<button class="text-button back" data-action="admin-list">${icon('back',14)} Ujian</button>${pageHead(exam.title,'',`${button(`${icon('eye',15)} Pratinjau siswa`,'preview','',dirty()||!exam.sections.length?'disabled':'')}${button(`${icon('settings',15)} Pengaturan`,'settings')}`)}<div class="row between"><span class="small muted">${locked?'12 peserta terdaftar · 2 sesi sudah dimulai':'12 peserta terdaftar · belum ada sesi'}</span></div>${locked?'<div class="notice warn mt"><strong>Aturan pengerjaan dan susunan section terkunci</strong>Sudah ada sesi ujian. Navigasi, timer, durasi, pengacakan, susunan Test, dan tampilan soal tidak dapat diubah. Tambahan waktu diberikan untuk sesi terdampak melalui Monitoring.</div>':''}<nav class="tabs" aria-label="Detail ujian">${[['overview','Ringkasan'],['tests','Tes & section'],['certificate','Sertifikat'],['registrations','Pendaftaran'],['results','Hasil'],['grading','Penilaian']].map(([id,label])=>`<button data-action="tab" data-value="${id}" ${!['overview','tests'].includes(id)?'disabled title="Di luar alur prototype"':''} class="${tab===id?'active':''}">${label}${id==='tests'?` (${sections.length})`:''}</button>`).join('')}</nav>${tab==='tests'?sectionEditor():overview()}`);
}
function overview(){return `<div class="overview"><div class="stack"><section class="card"><div class="card-head"><h2>Informasi ujian</h2></div><div class="card-body admin-overview-info"><section><div class="admin-overview-label">${icon('calendar',18)}<h3>Jadwal akses</h3></div><dl class="dl"><div><dt>Mulai akses</dt><dd>${formatted(exam.start)}</dd></div><div><dt>Batas akhir mulai sesi</dt><dd>${formatted(exam.end)}</dd></div></dl></section><section><div class="admin-overview-label">${icon('users',18)}<h3>Akses peserta</h3></div><dl class="dl"><div><dt>Akses gratis</dt><dd>${exam.free?'Aktif':'Nonaktif'}</dd></div><div><dt>Maksimal percobaan</dt><dd>${exam.attempts==null?'Tanpa batas':Math.max(1,exam.attempts)+' kali'}</dd></div><div><dt>Check-in</dt><dd>${exam.checkin?'Wajib check-in':'Tidak diperlukan'}</dd></div>${exam.checkin?`<div><dt>Jendela check-in</dt><dd>${exam.window} menit</dd></div><div><dt>Toleransi keterlambatan</dt><dd>${exam.grace} menit</dd></div>`:''}</dl></section><section><div class="admin-overview-label">${icon('eye',18)}<h3>Hasil & informasi tambahan</h3></div><dl class="dl"><div><dt>Tampilan hasil</dt><dd>${{hidden:'Disembunyikan',score_only:'Nilai saja',score_pembahasan:'Nilai & pembahasan'}[exam.result]}</dd></div>${exam.result!=='hidden'?`<div><dt>Rilis hasil</dt><dd>${formatted(exam.release)}</dd></div>`:''}<div><dt>Leaderboard</dt><dd>${exam.leaderboard?'Aktif':'Nonaktif'}</dd></div><div><dt>Aturan tambahan</dt><dd>${exam.rulesUrl?`<a class="overview-link" href="${esc(exam.rulesUrl)}" target="_blank" rel="noopener noreferrer">Lihat aturan lengkap ↗</a>`:exam.rulesNote?'Keterangan tambahan tersedia':'Tidak dicantumkan (opsional)'}</dd></div></dl></section></div></section><section class="card card-body"><div class="row between"><h2>Susunan section</h2>${button('Atur section','open-sections')}</div>${exam.sections.map((s,i)=>`<div class="row between rule"><div class="row"><span class="number">${i+1}</span><div><strong class="small">${esc(test(s.id).title)}</strong><p class="small muted">${presentationLabel(s)}</p></div></div><span class="small muted">${exam.timer==='per_test'?`${test(s.id).duration} menit`:'Timer ujian'}</span></div>`).join('')}</section></div><aside class="card card-body sticky admin-whatsapp" aria-labelledby="admin-whatsapp-title"><div class="row top">${icon('users',20)}<div><h2 id="admin-whatsapp-title">Grup WhatsApp kompetisi</h2><p class="small muted mt-sm">Komunikasi dan pengumuman peserta.</p></div></div><div class="mt">${exam.whatsappUrl?`<span class="badge green">Link tersedia</span><a class="overview-link" href="${esc(exam.whatsappUrl)}" target="_blank" rel="noopener noreferrer">${esc(exam.whatsappUrl)} ↗</a><p class="small muted mt-sm">Ajakan bergabung tampil pada detail ujian siswa.</p>`:'<strong class="small">Tidak dicantumkan</strong><p class="small muted mt-sm">Ajakan grup tidak ditampilkan kepada siswa. Bagian ini opsional.</p>'}</div><p class="small muted rule">Kelola link melalui <strong>Pengaturan → Informasi & jadwal akses</strong>.</p></aside></div>`;}

function sectionEditor(){const errors=issues(sections);return `<div class="split-editor"><section class="card"><div class="card-head row between top"><div><h2>Susunan section</h2><p class="small muted mt-sm">Satu Test menjadi satu section. Atur urutan dan tampilan soalnya di sini.</p></div>${button(`${icon('plus',14)} Tambah Test`,'library','',locked?'disabled':'')}</div><div class="card-body"><div class="section-list">${sections.map((s,i)=>sectionCard(s,i)).join('')||'<div class="notice warn">Belum ada section. Tambahkan Test untuk menyusun ujian.</div>'}</div></div><div class="save-bar"><span class="small ${dirty()?'muted':'subtle'}">${dirty()?'Ada perubahan belum disimpan':'Susunan sesuai konfigurasi tersimpan'}</span>${button('Simpan susunan','save-sections','primary',locked||!dirty()||errors.length?'disabled':'')}</div></section><aside class="stack sticky"><section class="card card-body"><h2>Aturan pengerjaan</h2>${summary(exam,sections)}${extraRulesAdmin()}<p class="small muted rule">Durasi section dan materi berasal dari sumber Test. Tampilan soal adalah pengaturan section khusus untuk ujian ini.</p></section>${errors.length?`<section class="notice error" role="alert"><strong>Tampilan section perlu diperbaiki</strong>${errors.map(e=>`<p>${esc(e.text)}</p>`).join('')}</section>`:`<section class="notice success"><strong>${sections.length?'Susunan section valid':'Tambahkan setidaknya satu Test'}</strong>${sections.length?'Materi soal tidak tersembunyi oleh pilihan tampilan.':'Ujian tanpa section belum dapat ditinjau oleh siswa.'}</section>`}</aside></div>`;}
function extraRulesAdmin(edit=false){const exists=!!(exam.rulesNote||exam.rulesUrl);return `<div id="extra-rules-admin">${exists&&!edit?`<div class="summary-line"><span>${icon('book')}</span><div class="extra-rules-saved"><div class="row between"><strong>Aturan tambahan</strong>${button('Edit','extra-rules-edit','text-button','type="button"')}</div>${exam.rulesNote?`<p class="rules-note">${esc(exam.rulesNote)}</p>`:''}${exam.rulesUrl?`<a class="overview-link" href="${esc(exam.rulesUrl)}" target="_blank" rel="noopener noreferrer">Baca aturan lengkap ↗</a>`:''}</div></div>`:`<form id="exam-extra-rules" class="exam-extra-rules rule"><label class="check extra-rules-toggle"><input type="checkbox" name="extra_rules_enabled" aria-controls="extra-rules-fields" aria-expanded="${exists}" ${exists?'checked':''}><span>Tambahkan aturan tambahan</span></label><fieldset id="extra-rules-fields" ${exists?'':'hidden disabled'}><p class="small muted mt-sm">Keterangan atau tautan aturan event akan tampil pada Cara mengerjakan siswa.</p><label class="mt-sm">Keterangan tambahan<textarea name="rules_note" placeholder="Contoh: Baca panduan teknis dan ketentuan peserta.">${esc(exam.rulesNote)}</textarea></label><label class="mt-sm">Link aturan lengkap<input type="url" name="rules_url" value="${esc(exam.rulesUrl)}" placeholder="https://..."></label></fieldset><p id="extra-rules-error" class="small error" role="alert" hidden></p><div id="extra-rules-actions" class="row mt-sm" ${exists?'':'hidden'}><button type="submit" class="button">Simpan aturan tambahan</button>${exists?button('Batal','extra-rules-cancel','','type="button"'):''}</div><span id="extra-rules-state" class="field-note" role="status"></span></form>`}</div>`;}
function updateExtraRulesForm(form){const enabled=form.elements.extra_rules_enabled.checked;$('#extra-rules-fields').hidden=!enabled;$('#extra-rules-fields').disabled=!enabled;$('#extra-rules-actions').hidden=!enabled&&!exam.rulesNote&&!exam.rulesUrl;form.elements.extra_rules_enabled.setAttribute('aria-expanded',String(enabled));}
function extraRulesStudent(){return exam.rulesNote||exam.rulesUrl?`<div class="summary-line exam-extra-rules-student">${icon('book',18)}<div><h3>Aturan tambahan dari penyelenggara</h3>${exam.rulesNote?`<p class="rules-note">${esc(exam.rulesNote)}</p>`:''}${exam.rulesUrl?`<a class="button extra-rules-link" href="${esc(exam.rulesUrl)}" target="_blank" rel="noopener noreferrer">${icon('link',15)} Baca aturan lengkap ↗</a>`:''}</div></div>`:'';}
function saveExtraRules(form){const enabled=form.elements.extra_rules_enabled.checked,url=enabled?form.elements.rules_url.value.trim():'',note=enabled?form.elements.rules_note.value.trim():'';let valid=!url;try{valid=valid||['http:','https:'].includes(new URL(url).protocol);}catch{}let error='';if(!valid)error='Gunakan link aturan dengan awalan http:// atau https://.';else if(enabled&&!url&&!note)error='Isi keterangan atau link aturan tambahan, atau matikan checkbox.';if(error){$('#extra-rules-error').hidden=false;$('#extra-rules-error').textContent=error;return;}exam.rulesUrl=url;exam.rulesNote=note;$('#extra-rules-admin').outerHTML=extraRulesAdmin();toast('Aturan tambahan contoh disimpan.');}
function sectionCard(s,i){const t=test(s.id),conflict=issues([s]).length;return `<article class="section-item"><div class="row top"><span class="number">${i+1}</span><div style="flex:1;min-width:130px"><h3>${esc(t.title)}</h3><small class="muted">${t.subject} · ${t.questions.length} soal</small></div><div class="section-actions">${[['up','↑','Naikkan',i===0],['down','↓','Turunkan',i===sections.length-1],['remove','×','Hapus',false]].map(([a,text,label,disabled])=>`<button data-action="${a}" data-id="${s.id}" aria-label="${label} ${t.title}" ${locked||disabled?'disabled':''}>${text}</button>`).join('')}</div></div><div class="section-fields"><label>Tampilan soal<select data-presentation="${s.id}" ${locked?'disabled':''} aria-invalid="${!!conflict}"><option value="one_per_page" ${s.presentation==='one_per_page'?'selected':''}>Satu soal per halaman</option><option value="all_on_page" ${s.presentation==='all_on_page'?'selected':''}>Semua soal dalam satu halaman</option></select><small>${s.presentation==='one_per_page'?'Siswa membuka soal satu per satu.':'Siswa menggulir seluruh soal dalam section ini.'}</small></label><div><span class="small muted">Waktu pengerjaan</span><p class="small mt-sm"><strong>${exam.timer==='per_test'?`${t.duration} menit`:'Mengikuti timer ujian'}</strong></p><span class="field-note">${exam.timer==='per_test'?'Durasi dari sumber Test':`${exam.duration} menit untuk seluruh section`}</span></div></div><div class="row between rule"><span class="small muted">Materi bersama${t.questions.some(q=>q.material)?' · 1 materi per soal':''}</span><button class="text-button" data-action="source" data-id="${s.id}">Lihat sumber Test ${icon('arrow',12)}</button></div>${conflict?`<div class="notice error mt-sm" role="alert"><strong>Materi soal ${t.questions.findIndex(q=>q.material)+1} tidak akan tampil</strong>Gunakan satu soal per halaman, atau perbaiki materi di sumber Test.<div class="mt-sm">${button('Gunakan satu soal per halaman','fix-presentation','',`data-id="${s.id}"`)}</div></div>`:''}</article>`;}
function openModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
const closeModal=()=>$('#modal').close();
function modalHeader(title,sub){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2><p class="small muted mt-sm">${sub}</p></div>${button(icon('close',16),'close','square','aria-label="Tutup"')}</div>`;}
function settings(create=false){const e=create?{...initialExam(),title:'',sections:[]}:exam;openModal(`${modalHeader(create?'Buat ujian':'Pengaturan ujian','Jadwal akses, aturan pengerjaan, dan pengaturan peserta dipisahkan agar tidak tertukar.')}<form id="settings-form" data-create="${create}"><div class="modal-body settings-layout"><div><section class="form-section"><h3>Informasi & jadwal akses</h3><p>Kapan siswa boleh memulai ujian. Ini bukan durasi pengerjaan.</p><label>Judul ujian<input name="title" value="${esc(e.title)}" required placeholder="Nama ujian"></label><div class="grid-2 mt"><label>Mulai akses<input type="datetime-local" name="start" value="${e.start}"></label><label>Batas akhir mulai sesi<input type="datetime-local" name="end" value="${e.end}"></label></div><p class="field-note">Sesi aktif tetap mengikuti timer pengerjaannya, meskipun batas mulai sesi sudah lewat.</p><label class="mt">Link grup WhatsApp kompetisi (opsional)<input name="whatsapp_url" type="url" value="${esc(e.whatsappUrl)}" placeholder="https://chat.whatsapp.com/..."><small>Ajakan bergabung tampil di bawah Informasi ujian pada detail siswa. Bergabung bukan syarat memulai ujian.</small></label></section><fieldset class="form-section" ${locked?'disabled':''}><h3>Aturan pengerjaan</h3><p>${locked?'Terkunci karena sudah ada sesi.':'Aturan berlaku untuk seluruh section dalam ujian ini.'}</p><fieldset><legend>Navigasi section</legend><div class="grid-2">${['free','sequential'].map(v=>`<label class="choice"><input type="radio" name="navigation" value="${v}" ${e.navigation===v?'checked':''}><span>${v==='free'?'Bebas pindah':'Berurutan'}<small>${v==='free'?'Boleh kembali ke section lain.':'Section selesai tidak dapat dibuka lagi.'}</small></span></label>`).join('')}</div></fieldset><fieldset class="mt"><legend>Waktu pengerjaan</legend><div class="grid-2">${['overall','per_test'].map(v=>`<label class="choice"><input type="radio" name="timer" value="${v}" ${e.timer===v?'checked':''}><span>${v==='overall'?'Seluruh ujian':'Per section'}<small>${v==='overall'?'Satu timer untuk semua section.':'Durasi diambil dari setiap Test.'}</small></span></label>`).join('')}</div></fieldset><div id="timer-help" class="notice mt-sm"></div><label class="mt-sm" id="duration-field">Durasi ujian (menit)<input name="duration" type="number" min="1" step="1" value="${e.duration}"></label><label class="check mt"><input type="checkbox" name="randomize" ${e.randomize?'checked':''}>Acak urutan soal per peserta</label><p class="field-note">Pengacakan tidak mengubah urutan section atau tampilan satu/semua soal.</p></fieldset><section class="form-section"><h3>Akses peserta</h3><p>Persyaratan untuk mengikuti ujian.</p><div class="grid-2">${[['free','Akses gratis'],['checkin','Wajib check-in'],['leaderboard','Aktifkan leaderboard']].map(([key,label])=>`<label class="check"><input type="checkbox" name="${key}" ${e[key]?'checked':''}>${label}</label>`).join('')}</div><div class="grid-2 mt"><label>Jendela check-in (menit)<input name="window" type="number" min="0" value="${e.window}"></label><label>Toleransi terlambat (menit)<input name="grace" type="number" min="0" value="${e.grace}"></label></div><label class="check mt"><input type="checkbox" name="multiple_attempts" aria-controls="attempts-field" ${e.attempts==null||e.attempts>1?'checked':''}>Izinkan lebih dari satu percobaan</label><p id="attempts-default" class="field-note">Siswa hanya dapat mengerjakan ujian satu kali.</p><div id="attempts-field" class="grid-2 mt-sm"><label id="attempts-count">Maksimal percobaan<input name="attempts" type="number" min="2" step="1" value="${e.attempts==null?2:Math.max(2,e.attempts)}"><small>Minimal 2 kali, termasuk percobaan pertama.</small></label><label class="check" style="align-self:center"><input type="checkbox" name="unlimited_attempts" ${e.attempts==null?'checked':''}>Tanpa batas</label></div></section><section class="form-section"><h3>Hasil ujian</h3><p>Atur apa yang terlihat setelah ujian selesai.</p><div class="grid-2"><label>Tampilan hasil<select name="result">${[['hidden','Disembunyikan'],['score_only','Nilai saja'],['score_pembahasan','Nilai & pembahasan']].map(([v,l])=>`<option value="${v}" ${e.result===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Waktu rilis hasil<input name="release" type="datetime-local" value="${e.release}"></label></div></section>${!create?`<section class="form-section"><h3>Kartu & layar selesai</h3><p>Field yang ada dipindahkan ke bagian tampilan tambahan.</p><label>Catatan kartu (satu baris per catatan)<textarea name="notes" placeholder="Maks. 5 catatan, masing-masing 55 karakter">${esc(e.notes)}</textarea></label><label class="mt-sm">Gambar layar selesai (URL)<input name="image" type="url" value="${esc(e.image)}" placeholder="https://..."></label><label class="mt-sm">Teks promosi layar selesai<textarea name="promo">${esc(e.promo)}</textarea></label></section>`:''}<div id="settings-error" class="notice error mt" role="alert" hidden></div></div><aside class="settings-summary"><h3>Yang perlu dibedakan</h3><ul><li><strong>Jadwal akses</strong>: kapan sesi baru boleh dimulai.</li><li><strong>Timer</strong>: berapa lama siswa mengerjakan.</li><li><strong>Navigasi</strong>: boleh kembali atau harus berurutan.</li><li><strong>Tampilan soal</strong>: satu atau semua soal, diatur pada masing-masing section.</li></ul><div class="rule small muted">${locked?'Tambahan waktu sesi dikelola melalui Monitoring.':'Setelah ada sesi, aturan pengerjaan dan susunan section tidak dapat diubah.'}</div></aside></div><div class="modal-footer"><span class="small muted">${create?'Setelah ini, tambahkan Test sebagai section.':'Perubahan hanya untuk data contoh prototype.'}</span><div class="row">${button('Batal','close')}<button class="button primary" type="submit">${create?'Buat & susun section':'Simpan pengaturan'}</button></div></div></form>`);updateSettingsHint();}
function updateSettingsHint(){const f=$('#settings-form');if(!f)return;const multiple=f.elements.multiple_attempts.checked,unlimited=multiple&&f.elements.unlimited_attempts.checked;$('#attempts-field').hidden=!multiple;$('#attempts-default').hidden=multiple;$('#attempts-count').hidden=unlimited;f.elements.attempts.disabled=!multiple||unlimited;f.elements.attempts.required=multiple&&!unlimited;f.elements.unlimited_attempts.disabled=!multiple;f.elements.multiple_attempts.setAttribute('aria-expanded',String(multiple));const timer=f.elements.timer.value,nav=f.elements.navigation.value;$('#duration-field').hidden=timer!=='overall';f.elements.duration.required=timer==='overall';const invalid=timer==='per_test'&&nav==='free';$('#timer-help').className=`notice mt-sm ${invalid?'error':''}`;$('#timer-help').textContent=invalid?'Timer per section hanya dapat digunakan dengan navigasi berurutan. Ubah navigasi atau gunakan timer seluruh ujian.':timer==='per_test'?'Timer dimulai ulang pada section berikutnya. Durasi mengikuti sumber Test, bukan field durasi ujian.':'Timer terus berjalan ketika berpindah section. Durasi Test tidak dipakai sebagai timer terpisah.';}
function isWhatsAppGroupLink(value){
  try{const url=new URL(value);return url.protocol==='https:'&&url.hostname==='chat.whatsapp.com'&&url.pathname.length>1;}
  catch{return false;}
}
function saveSettings(f){const data=new FormData(f), isNew=f.dataset.create==='true', base=isNew?{...initialExam(),sections:[]}:exam;const next={...base,title:String(data.get('title')).trim(),start:String(data.get('start')||''),end:String(data.get('end')||''),result:data.get('result'),release:data.get('release'),window:Number(data.get('window')),grace:Number(data.get('grace')),attempts:!data.has('multiple_attempts')?1:data.has('unlimited_attempts')?null:Number(data.get('attempts')),whatsappUrl:String(data.get('whatsapp_url')||'').trim(),notes:String(data.get('notes')||''),image:String(data.get('image')||''),promo:String(data.get('promo')||'')};for(const key of ['free','checkin','leaderboard'])next[key]=data.has(key);if(!locked){next.timer=data.get('timer');next.navigation=data.get('navigation');next.duration=Number(data.get('duration'));next.randomize=data.has('randomize');}let error='';if(!next.title)error='Isi judul ujian.';else if(next.whatsappUrl&&!isWhatsAppGroupLink(next.whatsappUrl))error='Gunakan link undangan grup WhatsApp dengan format https://chat.whatsapp.com/kode-undangan.';else if(next.start&&next.end&&next.end<=next.start)error='Batas akhir mulai sesi harus setelah waktu mulai akses.';else if(next.timer==='per_test'&&next.navigation==='free')error='Timer per section memerlukan navigasi berurutan.';else if(next.timer==='overall'&&(!Number.isInteger(next.duration)||next.duration<=0))error='Isi durasi ujian dengan bilangan bulat positif.';else if(data.has('multiple_attempts')&&next.attempts!==null&&(!Number.isInteger(next.attempts)||next.attempts<2))error='Isi maksimal percobaan minimal 2 kali, atau centang Tanpa batas.';else if(next.notes.split('\n').filter(Boolean).length>5||next.notes.split('\n').some(n=>n.length>55))error='Catatan kartu maksimal 5 baris, masing-masing 55 karakter.';if(error){$('#settings-error').hidden=false;$('#settings-error').textContent=error;$('#settings-error').scrollIntoView({block:'nearest'});return;}exam=next;if(isNew){sections=[];session=null;locked=false;$('#scenario').value='draft';}closeModal();tab=isNew?'tests':tab;view='admin-detail';render();toast(isNew?'Ujian contoh dibuat. Tambahkan Test sebagai section.':'Pengaturan contoh disimpan.');}
function openLibrary(){openModal(`${modalHeader('Tambahkan Test sebagai section','Materi dan durasi tetap mengikuti sumber Test. Tampilan soal dapat diatur setelah ditambahkan.')}<form id="library-form"><div class="modal-body"><label>Cari Test<input type="search" id="test-search" placeholder="Cari judul atau mata pelajaran"></label><div class="mt">${library.map(t=>{const exists=sections.some(s=>s.id===t.id);return `<div class="library-row" data-library-row="${t.id}"><input type="checkbox" name="test" value="${t.id}" id="add-${t.id}" ${exists?'disabled':''}><label for="add-${t.id}">${t.title}<small>${t.subject} · ${t.questions.length} soal · ${t.duration} menit</small></label>${badge(exists?'Sudah ditambahkan':'Materi bersama',exists?'gray':'')}</div>`}).join('')}</div><p id="library-empty" class="small muted mt" hidden>Tidak ada Test yang cocok.</p></div><div class="modal-footer"><span class="small muted">Test dipakai ulang tanpa menyalin isinya.</span><div class="row">${button('Batal','close')}<button type="submit" class="button primary">Tambahkan pilihan</button></div></div></form>`);}
function source(id){const t=test(id);openModal(`${modalHeader(t.title,'Sumber Test · pratinjau baca saja')}<div class="modal-body stack"><div class="grid-3"><div><span class="eyebrow">Mata pelajaran</span><p>${t.subject}</p></div><div><span class="eyebrow">Durasi Test</span><p>${t.duration} menit</p></div><div><span class="eyebrow">Jumlah soal</span><p>${t.questions.length} soal</p></div></div><div class="notice warn"><strong>Test dapat digunakan pada beberapa ujian</strong>Perubahan isi, judul, atau materi pada sumber Test akan berdampak pada ujian lain yang menggunakannya, termasuk sesi berjalan. Editor sumber tidak diubah dalam prototype ini.</div><div><h3>Instruksi</h3><p class="small muted mt-sm">${t.instructions}</p></div><div class="material">${t.material}</div><div><h3>Soal dalam Test</h3>${t.questions.map((q,i)=>`<div class="rule"><strong class="small">${i+1}. ${q.body}</strong><p class="small muted mt-sm">${q.material?'Memiliki materi sendiri · tidak cocok untuk semua soal dalam satu halaman':'Menggunakan materi bersama'}</p>${q.material?`<div class="material mt-sm">${q.material}</div>`:''}</div>`).join('')}</div></div><div class="modal-footer"><span class="small muted">Tampilan soal tetap diatur di ujian.</span>${button('Kembali ke susunan','close','primary')}</div>`);}
function studentList(){
  const e=session?.exam||exam, started=!!session, complete=!!session?.complete, upcoming=isUpcoming(e);
  const startDate=e.start?new Date(e.start):null,endDate=e.end?new Date(e.end):null;
  const dateOptions={day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'};
  const timeOptions={hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Jakarta'};
  const sameDate=startDate&&endDate&&startDate.toLocaleDateString('id-ID',dateOptions)===endDate.toLocaleDateString('id-ID',dateOptions);
  const access=sameDate?`<span class="exam-access-date">${startDate.toLocaleDateString('id-ID',dateOptions)}</span><span class="exam-access-time">${startDate.toLocaleTimeString('id-ID',timeOptions)}–${endDate.toLocaleTimeString('id-ID',timeOptions)} WIB</span>`:startDate||endDate?`${startDate?formatted(e.start):'Mulai kapan saja'}<span>${endDate?'Sampai '+formatted(e.end):'Tanpa batas akhir akses'}</span>`:'Tidak dibatasi jadwal';
  const limit=e.attempts==null?null:Math.max(1,e.attempts);
  const attemptText=started?`Percobaan ke-1${limit?' dari '+limit:''}`:limit?`Maksimal ${limit} percobaan`:'Percobaan tanpa batas';
  const answered=started?Object.keys(session.answers).length:0,total=totalQuestions(e.sections);
  const status=complete?'Selesai':started?'Sedang dikerjakan':upcoming?'Belum dibuka':'Siap dikerjakan';
  const action=complete?'completed':started?'resume':'student-detail';
  const actionText=complete?'Lihat penyelesaian':started?'Lanjutkan ujian':upcoming?'Lihat detail':'Lihat aturan ujian';
  return shell(`<header style="margin-bottom:28px"><h1>Kompetisi & Tryout</h1><p class="muted small mt-sm">Ikuti simulasi ujian dan kompetisi untuk mengasah kemampuan.</p></header><div class="eyebrow" style="margin-bottom:14px">${e.free?'Paket gratis':'Paket saya'}</div><div class="student-cards"><article class="card student-card" aria-labelledby="student-exam-title">
    <header class="exam-card-head"><span class="exam-card-kicker">${icon('exam',16)} Paket ujian</span>${badge(status,upcoming?'gray':complete?'green':started?'':'green')}</header>
    <h3 id="student-exam-title">${esc(e.title)}</h3>
    <dl class="exam-card-facts"><div><dt>${e.timer==='overall'?'Waktu pengerjaan':'Total waktu'}</dt><dd>${e.timer==='overall'?e.duration:totalMinutes(e.sections)} <span>menit</span></dd><small>${e.timer==='overall'?'Satu timer ujian':'Timer per section'}</small></div><div><dt>Section</dt><dd>${e.sections.length}</dd></div><div><dt>Soal</dt><dd>${total}</dd></div></dl>
    <div class="exam-card-access">${icon('calendar',32)}<div><span class="exam-card-label">Bisa mulai ujian</span><strong class="${sameDate?'exam-access-window':''}">${access}</strong></div></div>
    <div class="exam-card-rule">${icon(e.navigation==='sequential'?'lock':'arrow',16)}<div><strong>${navigationLabel(e)}</strong><p>${e.navigation==='sequential'?'Section selesai tidak bisa dibuka kembali.':'Boleh kembali ke section lain selama waktu tersedia.'}</p></div></div>
    ${started?`<div class="exam-card-progress"><div class="row between"><span>${answered} dari ${total} soal terjawab</span><span>${attemptText}</span></div><progress value="${answered}" max="${Math.max(1,total)}" aria-label="Soal terjawab">${answered} dari ${total}</progress></div>`:''}
    <footer class="exam-card-footer"><div><strong>${upcoming?opensIn(e):started?complete?'Ujian telah selesai':'Sesi sedang berlangsung':attemptText}</strong><span>${upcoming?attemptText:complete?'Tampilan hasil mengikuti pengaturan penyelenggara.':started?'Lanjutkan sesi yang sudah dimulai.':'Timer dimulai setelah konfirmasi.'}</span></div>${button(`${actionText} ${icon('arrow',14)}`,action,'primary',!started&&!e.sections.length?'disabled':'')}</footer>
  </article></div><div class="notice mt" style="max-width:700px"><strong>Mode pratinjau</strong>${upcoming?'Skenario sebelum akses dibuka. Waktu contoh: 2 Nov 2026, 08.00 WIB.':'Contoh peserta dianggap berada di dalam jadwal akses dan sudah terdaftar.'} Semua aksi, waktu, jawaban, dan penyimpanan di halaman ini adalah simulasi.</div>`,true);
}
function studentDetail(){
  const upcoming=isUpcoming(),startDate=exam.start?new Date(exam.start):null,endDate=exam.end?new Date(exam.end):null;
  const dateOptions={weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'};
  const timeOptions={hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Jakarta'};
  const sameDate=startDate&&endDate&&startDate.toLocaleDateString('id-ID',dateOptions)===endDate.toLocaleDateString('id-ID',dateOptions);
  const schedule=sameDate?`<p class="exam-info-date">${startDate.toLocaleDateString('id-ID',dateOptions)}</p><div class="exam-info-hours"><span>${startDate.toLocaleTimeString('id-ID',timeOptions)}</span><span class="muted" aria-hidden="true">–</span><span>${endDate.toLocaleTimeString('id-ID',timeOptions)}</span><small>WIB</small></div>`:`<dl class="exam-info-dates"><div><dt>Mulai</dt><dd>${startDate?formatted(exam.start):'Kapan saja'}</dd></div><div><dt>Batas mulai sesi</dt><dd>${endDate?formatted(exam.end):'Tanpa batas akhir'}</dd></div></dl>`;
  return shell(`<div class="student-detail"><button class="text-button back" data-action="student-list">${icon('back',14)} Kompetisi & Tryout</button><h1>${esc(exam.title)}</h1><p class="small muted mt-sm">Pahami susunan dan aturan ujian sebelum timer dimulai.</p><section class="card card-body mt exam-information" aria-labelledby="exam-information-title"><div class="row between"><h2 id="exam-information-title">Informasi ujian</h2>${badge(upcoming?'Belum dibuka':'Siap dimulai',upcoming?'gray':'green')}</div><div class="exam-info-grid"><div class="exam-info-fact"><div class="exam-info-label"><span>${icon('calendar',22)}</span><h3>Jadwal akses</h3></div><div class="exam-info-value">${schedule}</div><p class="exam-info-caption">Rentang waktu untuk memulai sesi.</p></div><div class="exam-info-fact"><div class="exam-info-label"><span>${icon('clock',22)}</span><h3>Waktu pengerjaan</h3></div><div class="exam-info-value"><p class="exam-info-duration">${exam.timer==='overall'?exam.duration:totalMinutes(exam.sections)} <span>menit${exam.timer==='per_test'?' total':''}</span></p><p class="exam-info-timer">${exam.timer==='per_test'?'Timer per section':'Satu timer seluruh ujian'}</p></div><p class="exam-info-caption">${exam.timer==='per_test'?'Dibagi mengikuti durasi setiap section.':'Dihitung sejak kamu memulai ujian.'}</p></div></div><div class="exam-info-note">${icon('lock',15)}<p>Batas akhir akses hanya membatasi mulai sesi baru. Sesi aktif tetap mengikuti timer pengerjaannya.</p></div></section>${exam.whatsappUrl?`<section class="card card-body mt exam-community" aria-labelledby="community-title"><div class="row top"><span class="title-icon">${icon('users',22)}</span><div><h2 id="community-title">Grup WhatsApp kompetisi</h2><p class="small muted mt-sm">Gabung untuk mendapatkan pengumuman dan informasi dari panitia.</p><p class="field-note">Opsional, bukan syarat mengikuti ujian.</p></div></div><a class="button" href="${esc(exam.whatsappUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Gabung grup WhatsApp (tab baru)">Gabung grup WhatsApp ↗</a></section>`:''}<section class="card card-body mt"><h2>Cara mengerjakan</h2>${summary(exam)}${extraRulesStudent()}<div class="rule"><h3>Susunan section</h3>${exam.sections.map((s,i)=>`<div class="row between rule"><div class="row"><span class="number">${i+1}</span><div><strong class="small">${test(s.id).title}</strong><p class="small muted">${test(s.id).questions.length} soal · ${presentationLabel(s).toLowerCase()}</p></div></div><strong class="small">${exam.timer==='per_test'?`${test(s.id).duration} menit`:'Timer bersama'}</strong></div>`).join('')}</div></section>${exam.checkin&&!upcoming?`<section class="card card-body mt"><h2>Check-in peserta</h2><p class="small muted mt-sm">Gunakan token contoh <strong>DEMO</strong>. Check-in tidak memulai timer pengerjaan.</p><div class="row mt-sm"><label style="flex:1">Token<input id="checkin-token" placeholder="Masukkan token"></label>${button('Check-in','checkin','primary')}</div><p id="checkin-feedback" class="small mt-sm muted" role="status">Belum check-in.</p></section>`:''}<section class="card card-body mt"><h2>${upcoming?'Ujian belum dibuka':'Siap memulai?'}</h2><p class="small muted mt-sm">${upcoming?`Kamu bisa membaca aturan dan susunan section sekarang. Akses mulai ujian dibuka pada ${formatted(exam.start)}.`:'Timer baru dimulai setelah konfirmasi mulai. Pastikan koneksi internet dan perangkat siap.'}</p>${upcoming?`<div class="notice mt">${icon('lock',16)} ${opensIn()}</div>`:'<label class="check mt"><input id="ready" type="checkbox">Saya memahami aturan waktu dan perpindahan section.</label>'}<div class="row between mt"><span class="small muted">${exam.attempts==null?'Percobaan tanpa batas':`Maksimal ${Math.max(1,exam.attempts)} percobaan`}</span>${button(upcoming?'Belum bisa dimulai':'Mulai ujian','start','primary','disabled')}</div><p class="field-note">${upcoming?'Kembali sesuai jadwal untuk memulai ujian.':exam.checkin?'Selesaikan check-in dan centang pemahaman aturan untuk melanjutkan.':'Centang pemahaman aturan untuk melanjutkan.'}</p></section></div>`,true);}
function startDialog(){if(isUpcoming()||!$('#ready')?.checked||exam.checkin&&!$('#checkin-token')?.dataset.valid)return;openModal(`${modalHeader('Mulai ujian sekarang?','Timer mulai berjalan setelah kamu menekan tombol di bawah.')}<div class="modal-body">${summary(exam)}<div class="notice warn mt-sm"><strong>${exam.navigation==='sequential'?'Section yang selesai tidak bisa dibuka kembali.':'Timer tidak berhenti saat kamu berpindah section.'}</strong>${exam.timer==='per_test'?`Section pertama: ${test(exam.sections[0].id).title} · ${test(exam.sections[0].id).duration} menit.`:`Waktu total: ${exam.duration} menit.`}</div></div><div class="modal-footer">${button('Belum, kembali','close')}${button('Ya, mulai ujian','start-confirm','primary')}</div>`);}
function startSession(){if(isUpcoming())return;session={exam:structuredClone(exam),sectionIndex:0,answers:{},flags:{},complete:false};questionIndex=0;mobileNav=false;locked=true;$('#scenario').value='locked';closeModal();route('student-session');}
const currentSection = () => session.exam.sections[session.sectionIndex];
const currentTest = () => {const t=test(currentSection().id);return session.exam.randomize?{...t,questions:[...t.questions].reverse()}:t;};
function questionCard(q,index,all){const answer=session.answers[q.id]??'';return `<article class="card question-card" id="q-${q.id}"><div class="row between"><span class="eyebrow">Soal ${index+1} dari ${currentTest().questions.length}</span><button class="text-button" data-action="flag" data-id="${q.id}">${icon('flag',13)} ${session.flags[q.id]?'Hapus tanda':'Tandai ragu'}</button></div>${q.material&&!all?`<div class="material mt-sm">${q.material}</div>`:''}<h3>${esc(q.body)}</h3>${q.options.map((o,i)=>`<label class="answer"><input type="radio" name="answer-${q.id}" data-answer="${q.id}" value="${i}" ${String(i)===String(answer)?'checked':''}><span class="answer-letter">${'ABCD'[i]}</span><span>${esc(o)}</span></label>`).join('')}${answer!==''?`<div class="row" style="justify-content:flex-end;margin-top:12px">${button('Hapus jawaban','clear-answer','',`data-id="${q.id}"`)}</div>`:''}</article>`;}
function runtime(){if(!session)return studentDetail();const e=session.exam,s=currentSection(),t=currentTest(),all=s.presentation==='all_on_page',q=t.questions[questionIndex],answered=t.questions.filter(q=>session.answers[q.id]!==undefined).length,allowed=e.navigation==='free',last=session.sectionIndex===e.sections.length-1,minutes=e.timer==='overall'?e.duration:t.duration;return `<div class="exam-session"><header class="session-header"><div class="title-icon" style="width:34px;height:34px">${icon('exam',18)}</div><div class="heading"><h2>${esc(t.title)}</h2><small>${esc(e.title)} · Section ${session.sectionIndex+1} dari ${e.sections.length}</small></div><span class="session-progress muted small">${answered}/${t.questions.length} terjawab</span><span class="session-save small" style="color:var(--success)">${icon('check',13)} Tersimpan</span><div class="timer"><small>Sisa waktu ${e.timer==='overall'?'ujian':'section ini'}</small><strong>${String(minutes).padStart(2,'0')}:00</strong></div>${allowed?button('Kumpulkan ujian','finish','danger'):''}</header><div class="session-body"><section class="question-pane"><div class="question-inner"><nav class="section-rail" aria-label="Section ujian">${e.sections.map((section,i)=>`<button data-action="section" data-index="${i}" class="${session.sectionIndex===i?'active':''}" ${!allowed?'disabled':''}>${!allowed&&i<session.sectionIndex?'✓ ':!allowed&&i>session.sectionIndex?'🔒 ':''}${test(section.id).title}</button>`).join('')}</nav><div class="row between"><span class="small muted">${all?'Semua soal section ini ada di halaman ini.':'Satu soal per halaman.'}</span><span class="small muted">${allowed?'Bebas pindah section':'Section berurutan'}</span></div><div class="notice mt-sm">${t.instructions}</div>${all||!q.material?`<div class="material mt">${t.material}</div>`:''}${(all?t.questions:[q]).map(item=>questionCard(item,t.questions.indexOf(item),all)).join('')}<div class="row between mt">${button(`${icon('back',13)} Sebelumnya`,'prev','',all||questionIndex===0?'disabled':'')}${!all&&questionIndex<t.questions.length-1?button(`Soal berikutnya ${icon('arrow',13)}`,'next'):button(allowed||last?'Kumpulkan ujian':'Selesaikan section','finish','danger')}</div></div></section><aside class="nav-rail"><button class="button mobile-nav" data-action="toggle-nav" aria-expanded="${mobileNav}">Navigasi soal · ${answered}/${t.questions.length} terjawab</button><div class="nav-content ${mobileNav?'expanded':''}"><h3>Soal di section ini</h3><div class="question-grid">${t.questions.map((item,i)=>`<button data-action="question" data-index="${i}" class="q-number ${session.answers[item.id]!==undefined?'answered':''} ${i===questionIndex?'current':''} ${session.flags[item.id]?'flagged':''}" aria-label="Soal ${i+1}${session.answers[item.id]!==undefined?', terjawab':', belum dijawab'}">${i+1}</button>`).join('')}</div><div class="legend"><span><i class="swatch fill"></i>Terjawab</span><span><i class="swatch"></i>Belum dijawab</span><span><i class="swatch flag"></i>Ditandai ragu</span></div></div><div class="notice mt"><strong>${e.timer==='per_test'?'Timer untuk section ini':'Timer untuk seluruh ujian'}</strong>${e.timer==='per_test'?'Saat waktu habis, section ditutup dan lanjut ke section berikutnya. Pada section terakhir, ujian dikumpulkan.':'Saat waktu habis, seluruh ujian dikumpulkan.'}</div><p class="small muted mt">${allowed?'Kamu dapat membuka kembali section lain selama waktu ujian tersedia.':'Setelah diselesaikan, jawaban section ini tidak dapat diubah lagi.'}</p><p class="small subtle rule">Prototype: timer dan penyimpanan disimulasikan.</p></aside></div></div>`;}
function finishDialog(){const e=session.exam,whole=e.navigation==='free'||session.sectionIndex===e.sections.length-1,scope=whole?e.sections.flatMap(s=>test(s.id).questions):currentTest().questions,empty=scope.filter(q=>session.answers[q.id]===undefined).length;openModal(`${modalHeader(whole?'Kumpulkan ujian?':'Selesaikan section ini?',whole?'Setelah dikumpulkan, jawaban tidak dapat diubah.':`Section ${currentTest().title} akan dikunci.`)}<div class="modal-body"><div class="notice ${empty?'warn':'success'}"><strong>${empty?`${empty} soal belum dijawab`:'Semua soal sudah dijawab'}</strong>${empty?'Kamu tetap dapat melanjutkan. Soal yang kosong akan tetap tanpa jawaban.':'Periksa kembali jawaban sebelum melanjutkan.'}</div>${!whole?`<p class="mt small">Berikutnya: <strong>${test(e.sections[session.sectionIndex+1].id).title}</strong>${e.timer==='per_test'?` · ${test(e.sections[session.sectionIndex+1].id).duration} menit dengan timer baru.`:'. Timer ujian tetap berjalan.'}</p>`:''}</div><div class="modal-footer">${button('Kembali periksa','close')}${button(whole?'Ya, kumpulkan ujian':'Ya, lanjut section berikutnya','confirm-finish','danger')}</div>`);}
function complete(){const e=session?.exam||exam;return shell(`<div class="completion card card-body"><div class="title-icon">${icon('check',24)}</div><h1>Ujian selesai</h1><p class="muted mt">${esc(e.title)}</p><p class="small mt">Jawaban telah dikumpulkan dalam simulasi prototype ini.</p><div class="notice mt"><strong>${e.result==='hidden'?'Hasil belum ditampilkan':e.release?'Hasil mengikuti jadwal rilis':'Tampilan hasil diatur oleh penyelenggara'}</strong>${e.result==='hidden'?'Penyelenggara mengatur ketersediaan hasil.':e.release?formatted(e.release):'Penilaian dan pembahasan tidak disimulasikan dalam prototype.'}</div>${button('Kembali ke daftar ujian','student-list','primary mt')}</div>`,true);}
function render(){document.querySelectorAll('[data-go]').forEach(b=>b.classList.toggle('selected',view.startsWith(b.dataset.go)||(b.dataset.go==='admin'&&view.startsWith('tests-'))));const student=view.startsWith('student')||view==='completed';$('#admin-scenario-label').hidden=student||view.startsWith('tests-');$('#student-scenario-label').hidden=!student;$('#student-scenario').value=accessPreview;$('#student-scenario').disabled=!!session||!exam.start||!(exam.end||exam.checkin);$('#app').innerHTML=view.startsWith('tests-')?renderTests():view==='admin-list'?adminList():view==='admin-detail'?detail():view==='student-list'?studentList():view==='student-detail'?studentDetail():view==='student-session'?runtime():complete();}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const a=target.dataset.action,id=target.dataset.id,index=Number(target.dataset.index);if(a==='close'){closeModal();return;}if(a==='extra-rules-edit'||a==='extra-rules-cancel'){$('#extra-rules-admin').outerHTML=extraRulesAdmin(a==='extra-rules-edit');return;}if(a==='clear-exam-search'){$('#exam-search').value='';filterExams();$('#exam-search').focus();}else if(a==='admin-list'){legacy=false;route(a);}else if(a==='admin-detail'||a==='legacy-detail'){legacy=a==='legacy-detail';tab='tests';route('admin-detail');}else if(a==='tab'){tab=target.dataset.value;render();}else if(a==='open-sections'){tab='tests';render();}else if(a==='settings')settings();else if(a==='create'){if(locked){toast('Pilih skenario belum ada sesi untuk membuat ujian contoh.');return;}settings(true);}else if(a==='library'&&!locked)openLibrary();else if(a==='source')source(id);else if(['up','down','remove'].includes(a)&&!locked){const i=sections.findIndex(s=>s.id===id);if(a==='remove')sections.splice(i,1);else{const dest=i+(a==='up'?-1:1);if(dest>=0&&dest<sections.length)[sections[i],sections[dest]]=[sections[dest],sections[i]];}render();}else if(a==='fix-presentation'&&!locked){sections.find(s=>s.id===id).presentation='one_per_page';render();}else if(a==='save-sections'&&!locked){if(issues(sections).length)return;exam.sections=structuredClone(sections);render();toast('Susunan section contoh disimpan.');}else if(a==='preview'){if(dirty()){toast('Simpan susunan section sebelum pratinjau.');return;}if(!exam.sections.length)return;route('student-detail');}else if(['student-list','student-detail'].includes(a))route(a);else if(a==='checkin'){const input=$('#checkin-token'),valid=input.value.trim().toUpperCase()==='DEMO';input.dataset.valid=valid?'true':'';$('#checkin-feedback').textContent=valid?'Check-in berhasil. Timer belum dimulai.':'Token contoh tidak sesuai. Gunakan DEMO.';updateReady();}else if(a==='start')startDialog();else if(a==='start-confirm')startSession();else if(a==='resume')route('student-session');else if(a==='completed')route('completed');else if(a==='section'&&session.exam.navigation==='free'){session.sectionIndex=index;questionIndex=0;render();}else if(a==='question'){questionIndex=index;if(currentSection().presentation==='all_on_page')$(`#q-${currentTest().questions[index].id}`).scrollIntoView({block:'start',behavior:'smooth'});else render();}else if(a==='prev'||a==='next'){questionIndex+=a==='prev'?-1:1;render();}else if(a==='flag'){session.flags[id]=!session.flags[id];render();}else if(a==='clear-answer'){delete session.answers[id];render();}else if(a==='toggle-nav'){mobileNav=!mobileNav;render();}else if(a==='finish')finishDialog();else if(a==='confirm-finish'){const e=session.exam;if(e.navigation==='free'||session.sectionIndex===e.sections.length-1){session.complete=true;closeModal();route('completed');}else{session.sectionIndex++;questionIndex=0;closeModal();render();}}});
function updateReady(){const ready=$('#ready');if(ready)$('[data-action="start"]').disabled=!ready.checked||(exam.checkin&&!$('#checkin-token').dataset.valid);}
document.addEventListener('change',event=>{const el=event.target;if(el.name==='extra_rules_enabled')updateExtraRulesForm(el.form);else if(el.matches('[data-presentation]')&&!locked){sections.find(s=>s.id===el.dataset.presentation).presentation=el.value;render();}else if(el.closest('#settings-form'))updateSettingsHint();else if(el.id==='ready')updateReady();else if(el.matches('[data-answer]')){const pane=$('.question-pane'),body=$('.session-body'),y=pane.scrollTop,bodyY=body.scrollTop;session.answers[el.dataset.answer]=el.value;render();$('.question-pane').scrollTop=y;$('.session-body').scrollTop=bodyY;}});
function filterExams(){const q=$('#exam-search').value.trim().toLocaleLowerCase('id-ID');let count=0;document.querySelectorAll('[data-exam-row]').forEach(row=>{row.hidden=!row.querySelector('.exam-link').textContent.toLocaleLowerCase('id-ID').includes(q);if(!row.hidden)count++;});$('#empty-search').hidden=count>0;$('#exam-count').textContent=`${count} ujian`;$('[data-action="clear-exam-search"]').hidden=!$('#exam-search').value;}

document.addEventListener('input',event=>{if(event.target.closest('#exam-extra-rules')){$('#extra-rules-state').textContent='Belum disimpan.';$('#extra-rules-error').hidden=true;}if(event.target.id==='exam-search')filterExams();if(event.target.id==='test-search'){const q=event.target.value.toLowerCase();let count=0;document.querySelectorAll('[data-library-row]').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(q);if(!row.hidden)count++;});$('#library-empty').hidden=count>0;}if(event.target.id==='checkin-token'){event.target.dataset.valid='';updateReady();}});
document.addEventListener('submit',event=>{if(event.target.id==='exam-extra-rules'){event.preventDefault();saveExtraRules(event.target);}else if(event.target.id==='settings-form'){event.preventDefault();saveSettings(event.target);}else if(event.target.id==='library-form'){event.preventDefault();const selected=new FormData(event.target).getAll('test');if(!selected.length){toast('Pilih Test yang ingin ditambahkan.');return;}for(const id of selected)if(!sections.some(s=>s.id===id))sections.push({id,presentation:'one_per_page'});closeModal();render();toast('Test ditambahkan. Simpan susunan untuk menerapkan.');}});
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(b.dataset.go==='student'&&dirty()){toast('Simpan atau kembalikan perubahan section sebelum membuka pratinjau siswa.');return;}route(b.dataset.go==='admin'?'admin-list':'student-list');});
$('#student-scenario').onchange=event=>{accessPreview=event.target.value;render();};
$('#scenario').onchange=event=>{locked=event.target.value==='locked';if(locked)sections=structuredClone(exam.sections);render();};
$('#reset').onclick=()=>{resetTestPrototype();exam=initialExam();sections=structuredClone(exam.sections);session=null;legacy=false;locked=false;accessPreview='ready';$('#scenario').value='draft';tab='tests';closeModal();route('admin-list');toast('Prototype dikembalikan ke data awal.');};
if(location.hash==='#tests-list')view='tests-list';
if(location.hash==='#tests-detail')view='tests-detail';
if(location.hash==='#admin-detail')view='admin-detail';
if(location.hash==='#admin-overview'){view='admin-detail';tab='overview';}
if(location.hash==='#student-detail')view='student-detail';
if(location.hash==='#student-list')view='student-list';
render();
